/**
 * Los quizzes nuevos en español (Nov 23 2026): el gemelo de lib/site/quizBank2.ts, pregunta por pregunta, con las mismas respuestas,
 * las mismas páginas de "aprende más" (la española cuando existe) y los mismos dibujos de cancha (SPOTS; solo cambia el texto
 * alternativo). Palabras de las guías en español: arco, cancha, saque de banda, saque de meta, penal; nunca "portería".
 */
const R=(s:string)=>`/learn/soccer-rules/${s}`,T=(s:string)=>`/learn/soccer-terms/${s}`,P=(s:string)=>`/learn/soccer-positions/${s}`,X=(s:string)=>`/exhibits/${s}`;
