const NUM='/learn/soccer-positions/numbers',BALL='/learn/soccer-ball-size-by-age',FIELD='/learn/soccer-field-size-by-age',AGES='/learn/soccer-age-groups',FMT='/learn/7v7-9v9-11v11';
const IFAB='https://www.theifab.com/laws/latest/';
const law=(n:string,page:string)=>({name:`Reglas de Juego de la IFAB: ${n} (en inglés)`,url:IFAB+page});
const USS={name:'U.S. Soccer: normas de fútbol reducido (en inglés)',url:'https://www.ussoccer.com/stories/2017/08/five-things-to-know-how-smallsided-standards-will-change-youth-soccer'};
const USYS={name:'US Youth Soccer: reglamento de jugadores y juego, 2025 (en inglés)',url:'https://www.usyouthsoccer.org/wp-content/uploads/sites/160/2025/12/Policy-on-Players-and-Playing-Rules-_APP-12.05.2025.pdf'};
const USSH={name:'U.S. Soccer: programa de seguridad Recognize to Recover (en inglés)',url:'https://www.ussoccer.com/stories/2015/12/us-soccer-announces-recognize-to-recover-player-health-and-safety-program'};
const W=(t:string,page:string)=>({name:`Wikipedia: ${t}`,url:`https://es.wikipedia.org/wiki/${page}`});
const SITE=(t:string,path:string)=>({name:`Futbol Island: ${t}`,url:`https://futbolisland.app${path}`});
const c=(q:string,options:string[],correct:number,explain:string,more:string,fact?:string):BankQuestion=>({kind:'choice',q,options,correct,explain,more,...(fact?{fact}:{})});
const tf=(q:string,yes:boolean,explain:string,more:string):BankQuestion=>({kind:'truefalse',q,options:['Verdadero','Falso'],correct:yes?0:1,explain,more});
const sp=(q:string,options:string[],correct:number,explain:string,more:string,spot:BankSpot):BankQuestion=>({kind:'spot',q,options,correct,explain,more,spot});
const od=(q:string,steps:string[],explain:string,more:string):BankQuestion=>({kind:'order',q,options:steps,correct:0,explain,more});
const S=(k:keyof typeof SPOTS,alt:string):BankSpot=>({...(SPOTS[k] as Omit<BankSpot,'alt'>),alt});
